   char *str = new char[n + 1]; \
   vsprintf(str, format, arg); \
   HANDLE h = CreateFile(hfile, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL); \
